<script setup lang="ts">const{listFinancialHistory}=useAppData();const history=ref<any[]>([]),historyLoading=ref(false),historyError=ref('');const resourceLabel=(resource:string)=>({products:'Produto',filaments:'Filamento',printers:'Impressora',marketplaces:'Marketplace'}[resource]||resource);const historyTitle=(entry:any)=>`${resourceLabel(entry.resource)} #${entry.resourceId}`;onMounted(async()=>{historyLoading.value=true;try{history.value=await listFinancialHistory()}catch(error:any){historyError.value=error?.data?.error||'Historico financeiro indisponivel para este perfil.'}finally{historyLoading.value=false}})</script>
<template><PanelCard title="Histórico de alterações financeiras" subtitle="Versões registradas de custos, preços e taxas. Os valores não sobrescrevem vendas já realizadas."><div v-if="historyLoading" class="empty-state">Carregando histórico...</div><div v-else-if="historyError" class="empty-state">{{historyError}}</div><div v-else-if="!history.length" class="empty-state">Ainda não há alterações financeiras registradas.</div><div v-else class="table-scroll"><table class="data-table"><thead><tr><th>Data</th><th>Recurso</th><th>Origem</th><th>Valores registrados</th></tr></thead><tbody><tr v-for="entry in history" :key="entry.id"><td>{{new Date(entry.createdAt).toLocaleString('pt-BR')}}</td><td>{{historyTitle(entry)}}</td><td>{{entry.source}}</td><td><span v-for="(value,key) in entry.snapshot" :key="key" class="history-value">{{key}}: {{typeof value==='number'?formatCurrency(value):value}}</span></td></tr></tbody></table></div></PanelCard></template>
<style scoped>.history-value{display:inline-block;margin:2px 6px 2px 0;padding:4px 7px;border-radius:6px;background:#f1f4f8;font-size:12px}</style>
